WITH "authorized_Printing" AS NOT MATERIALIZED (SELECT "root"."id" AS "id" FROM "Printing" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"authorized_Deck" AS NOT MATERIALIZED (SELECT "root"."entity" AS "entity", "root"."id" AS "id", "leaf"."label" AS "label", "root"."name" AS "name", NULL AS "printing.id" FROM "Deck" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"batch_selected_rows_0" AS MATERIALIZED ( SELECT "t".* FROM "authorized_Printing" "t"    ),
"batch_selected_roots_1" AS MATERIALIZED ( SELECT "t"."id" AS "id"  FROM "batch_selected_rows_0" "t" ),
"batch_source_2" AS MATERIALIZED (SELECT "cj3"."printing.id" AS "__parent_id", "cj3".* FROM "DeckPrinting" "cj3" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj3"."printing.id" = "t"."id"),
"flat_targets_fb4" AS MATERIALIZED (SELECT "ct1".* FROM "authorized_Deck" "ct1" WHERE "ct1"."id" IN (SELECT "__edge_row"."deck.id" FROM "batch_source_2" AS "__edge_row")),
"flat_base_fb4" AS MATERIALIZED (SELECT "__edge_row"."__parent_id", "ct1"."id" AS "__item_id", "ct1".*, (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $1) THEN TRUE ELSE FALSE END) AS "__batch_filter", (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $2) THEN TRUE ELSE FALSE END) AS "__batch_filter_matched" FROM "batch_source_2" AS "__edge_row" JOIN "flat_targets_fb4" "ct1" ON "ct1"."id" = "__edge_row"."deck.id"),
"flat_flags_fb4" AS MATERIALIZED (SELECT "__parent_id", "__item_id", bool_or("__batch_filter") AS "__batch_filter", bool_or("__batch_filter_matched") AS "__batch_filter_matched" FROM "flat_base_fb4" GROUP BY "__parent_id", "__item_id"),
"flat_scope_ids_fb4" AS MATERIALIZED (SELECT "__parent_id", "__item_id", row_number() OVER (PARTITION BY "__parent_id" ORDER BY "__item_id") AS "__ordinal" FROM (SELECT DISTINCT "__parent_id", "__item_id" FROM "flat_flags_fb4" WHERE "__batch_filter" IS TRUE ) AS "__identity"),
"flat_scope_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("flat_base_fb4"."__parent_id", "flat_base_fb4"."__item_id") "flat_base_fb4".*, "flat_scope_ids_fb4"."__ordinal" FROM "flat_base_fb4" JOIN "flat_scope_ids_fb4" ON "flat_scope_ids_fb4"."__parent_id" = "flat_base_fb4"."__parent_id" AND "flat_scope_ids_fb4"."__item_id" = "flat_base_fb4"."__item_id" WHERE "flat_scope_ids_fb4"."__ordinal" > 0),
"flat_rows_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("fi5"."__parent_id", "fi5"."__item_id") "fi5"."__parent_id", "fi5"."__item_id", fi5."id" AS "id", fi5."name" AS "name", fi5."entity" AS "entity", fi5."label" AS "label", "flat_flags_fb4"."__batch_filter", "flat_flags_fb4"."__batch_filter_matched" FROM "flat_base_fb4" "fi5" JOIN "flat_flags_fb4" ON "flat_flags_fb4"."__parent_id" = "fi5"."__parent_id" AND "flat_flags_fb4"."__item_id" = "fi5"."__item_id" ),
"flat_rows_filtered_fb4" AS MATERIALIZED (SELECT * FROM "flat_rows_fb4" WHERE "__batch_filter" IS TRUE),
"flat_rows_matched_fb4" AS MATERIALIZED (SELECT * FROM "flat_rows_fb4" WHERE "__batch_filter_matched" IS TRUE),
"flat_counts_fb4" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_rows_matched_fb4" GROUP BY "__parent_id"),
"flat_items_fb4" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(row_to_json("__item") ORDER BY "__item"."__ordinal") FILTER (WHERE "__ordinal" > 0), '[]'::json) AS "__items" FROM (SELECT row_number() OVER (PARTITION BY "__parent_id" ORDER BY "__child"."__item_id") AS "__ordinal", "__child".* FROM "flat_rows_filtered_fb4" AS "__child") AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_rows_matched_fb4" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id"),
"flat_base_fr9" AS MATERIALIZED (SELECT "cj8"."printing.id" AS "__parent_id", "cj8"."quantity" AS "quantity", "cj8"."printing.id" AS "printing", "cj8"."deck.id" AS "deck", (CASE WHEN ("cj8"."quantity" IS NOT DISTINCT FROM $3) THEN TRUE ELSE FALSE END) AS "__batch_filter", (CASE WHEN ("cj8"."quantity" IS NOT DISTINCT FROM $4) THEN TRUE ELSE FALSE END) AS "__batch_filter_matched" FROM "DeckPrinting" "cj8" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj8"."printing.id" = "t"."id"),
"flat_rows_filtered_fr9" AS MATERIALIZED (SELECT * FROM "flat_base_fr9" WHERE "__batch_filter" IS TRUE),
"flat_rows_matched_fr9" AS MATERIALIZED (SELECT * FROM "flat_base_fr9" WHERE "__batch_filter_matched" IS TRUE),
"flat_counts_fr9" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_base_fr9" GROUP BY "__parent_id"),
"flat_items_fr9" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(json_build_object('quantity', "__item"."quantity") ORDER BY "__item"."__ordinal") FILTER (WHERE "__ordinal" > 0), '[]'::json) AS "__items" FROM (SELECT row_number() OVER (PARTITION BY "__parent_id" ORDER BY "__child"."printing", "__child"."deck") AS "__ordinal", "__child".* FROM "flat_rows_filtered_fr9" AS "__child") AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_rows_matched_fr9" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id") SELECT t."id" AS "id", "bc6"."__items" AS "decks", "bc6"."__matched" AS "decks__matched", "bn7"."__total" AS "decks__total", "bc10"."__items" AS "entries", "bc10"."__matched" AS "entries__matched", "bn11"."__total" AS "entries__total" FROM "batch_selected_rows_0" "t" LEFT JOIN "flat_items_fb4" "bc6" ON "bc6"."__parent_id" = "t"."id" LEFT JOIN "flat_counts_fb4" "bn7" ON "bn7"."__parent_id" = "t"."id" LEFT JOIN "flat_items_fr9" "bc10" ON "bc10"."__parent_id" = "t"."id" LEFT JOIN "flat_counts_fr9" "bn11" ON "bn11"."__parent_id" = "t"."id"  
